fn merge_contract_regions_disjoint<T>(src: *const T, dst: *mut T, len: usize) -> bool {
    let Some(bytes) = size_of::<T>().checked_mul(len) else {
        return false;
    };
    bytes == 0
        || !crate::ub_checks::same_allocation(src, dst)
        || (src as usize).abs_diff(dst as usize) >= bytes
}

