impl ContractConditionsData {
    /// Constructs a [`Self::Modifies`] from the contents of the decorating attribute.
    ///
    /// Responsible for parsing the attribute.
    fn new_modifies(attr: TokenStream, output: &mut TokenStream2) -> Self {
        let attr = chunks_by(TokenStream2::from(attr), is_token_stream_2_comma)
            .map(syn::parse2)
            .filter_map(|expr| match expr {
                Err(e) => {
                    output.extend(e.into_compile_error());
                    None
                }
                Ok(expr) => Some(expr),
            })
            .collect();

        ContractConditionsData::Modifies { attr }
    }

pub fn split_for_remembers(stmts: &[Stmt], contract_mode: ContractMode) -> (&[Stmt], &[Stmt]) {
    let mut pos = 0;

    let check_str = match contract_mode {
        ContractMode::SimpleCheck => "assume",
        ContractMode::Replace | ContractMode::Assert => "assert",
    };

    for stmt in stmts {
        if stmt_is_precondition(stmt, check_str) {
            pos += 1;
        }
    }
    stmts.split_at(pos)

/// Whether `stmt` is a precondition statement that [`split_for_remembers`] must
/// place remembers after. Preconditions are emitted either as a bare
/// `kani::assume(..)` / `kani::assert(..)` call statement, or wrapped in a
/// clause-depth bracket (see `helpers::bracket_clause_stmt`), i.e.
/// `{ let __kani_clause_guard = ..; kani::assume(#cond); }`. Both forms must be
/// recognized, otherwise remembers get inserted before the precondition and
/// `old(..)` expressions are evaluated without the precondition's constraints.
fn stmt_is_precondition(stmt: &Stmt, check_str: &str) -> bool {
    match stmt {
        Stmt::Expr(Expr::Block(ExprBlock { block, .. }), _) => {
            block.stmts.iter().any(|inner| stmt_is_precondition(inner, check_str))
        }
        Stmt::Expr(expr, _) => is_kani_check_call(expr, check_str),
        _ => false,
    }

/// When a `#[kani::ensures(|result|expr)]` is expanded, this function is called on with `build_ensures(|result|expr)`.
/// This function goes through the expr and extracts out all the `old` expressions and creates a sequence
/// of statements that instantiate these expressions as `let remember_kani_internal_x = old_expr;`
/// where x is a unique hash. This is returned as the first return parameter. The second
/// return parameter is the expression formed by passing in the result variable into the input closure.
pub fn build_ensures(data: &ExprClosure) -> (TokenStream2, Expr) {
    let mut remembers_exprs = HashMap::new();
    let mut vis = OldVisitor { t: OldLifter::new(), remembers_exprs: &mut remembers_exprs };
    let expr = &mut data.clone();
    vis.visit_expr_closure_mut(expr);

    let remembers_stmts: TokenStream2 =
        remembers_exprs.iter().fold(quote!(), |collect, (ident, expr)| {
            let bracketed =
                crate::sysroot::contracts::helpers::bracket_clause_expr(quote!((#expr).clone()));
            quote!(let #ident = #bracketed; #collect)
        });

    let result: Ident = Ident::new(INTERNAL_RESULT_IDENT, Span::call_site());
    (remembers_stmts, Expr::Verbatim(quote!(kani::internal::apply_closure(#expr, &#result))))
}

impl<T: OldTrigger> syn::visit_mut::VisitMut for OldVisitor<'_, T> {
    fn visit_expr_mut(&mut self, ex: &mut Expr) {
        let trigger = match &*ex {
            Expr::Call(call @ ExprCall { func, attrs, args, .. }) => match func.as_ref() {
                Expr::Path(ExprPath {
                    attrs: func_attrs,
                    qself: None,
                    path: Path { leading_colon: None, segments },
                }) if segments.len() == 1
                    && segments.first().is_some_and(|sgm| sgm.ident == "old") =>
                {
                    let first_segment = segments.first().unwrap();
                    assert_spanned_err!(first_segment.arguments.is_empty(), first_segment);
                    assert_spanned_err!(attrs.is_empty(), call);
                    assert_spanned_err!(func_attrs.is_empty(), func);
                    assert_spanned_err!(args.len() == 1, call);
                    true
                }
                _ => false,
            },
            _ => false,
        };
        if trigger {
            let span = ex.span();
            let new_expr = if let Expr::Call(ExprCall { args, .. }) = ex {
                self.t
                    .trigger(args.iter_mut().next().unwrap(), span, self.remembers_exprs)
                    .then(|| args.pop().unwrap().into_value())
            } else {
                unreachable!()
            };
            if let Some(new) = new_expr {
                let _ = std::mem::replace(ex, new);
            }
        } else {
            syn::visit_mut::visit_expr_mut(self, ex)
        }

impl OldTrigger for OldLifter {
    fn trigger(
        &mut self,
        e: &mut Expr,
        _: Span,
        remembers_exprs: &mut HashMap<Ident, Expr>,
    ) -> bool {
        let mut denier = OldVisitor { t: OldDenier, remembers_exprs };
        // This ensures there are no nested calls to `old`
        denier.visit_expr_mut(e);
        let mut hasher = DefaultHasher::new();
        e.hash(&mut hasher);
        let ident =
            Ident::new(&format!("remember_kani_internal_{:x}", hasher.finish()), Span::call_site());
        // save the original expression to be lifted into the past remember environment
        remembers_exprs.insert(ident.clone(), (*e).clone());
        // change the expression to refer to the new remember variable
        let _ = std::mem::replace(e, Expr::Verbatim(quote!((#ident))));
        true
    }

match &self.condition_type {
    ContractConditionsData::Requires { attr } => {
        let assume_bracketed = bracket_clause_stmt(quote!(kani::assume(#attr);));
        quote!({
            #assume_bracketed
            #(#body_stmts)*
        })
    }
    ContractConditionsData::Ensures { attr } => {
        let (remembers, ensures_clause) = build_ensures(attr);

        // The code that enforces the postconditions and cleans up the shallow
        // argument copies (with `mem::forget`).
        let ensures_bracketed = bracket_clause_expr(quote!(#ensures_clause));
        let exec_postconditions = quote!(
            kani::assert(#ensures_bracketed, stringify!(#attr_copy));
        );

        let return_expr = body_stmts.pop();

        let (assumes, rest_of_body) =
            split_for_remembers(&body_stmts[..], ContractMode::SimpleCheck);

        quote!({
            #(#assumes)*
            #remembers
            #(#rest_of_body)*
            #exec_postconditions
            #return_expr
        })

ContractConditionsData::Modifies { attr } => {
    let wrapper_arg_ident = Ident::new(WRAPPER_ARG, Span::call_site());
    let wrapper_tuple = body_stmts.iter_mut().find_map(|stmt| {
        if let Stmt::Local(Local {
            pat: Pat::Ident(PatIdent { ident, .. }),
            init: Some(LocalInit { expr, .. }),
            ..
        }) = stmt
        {
            (ident == &wrapper_arg_ident).then_some(expr.as_mut())
        } else {
            None
        }
    });
    if let Some(Expr::Tuple(values)) = wrapper_tuple {
        values.elems.extend(attr.iter().map(|attr| {
            let bracketed = bracket_clause_expr(quote!(#attr as *const _));
            let expr: Expr = parse_quote!(#bracketed);
            expr
        }));
    } else {
        unreachable!("Expected tuple but found `{wrapper_tuple:?}`")
    }
    quote!({#(#body_stmts)*})

/// Initialize the list of statements for the check closure body.
fn initial_check_stmts(&self) -> Vec<syn::Stmt> {
    let modifies_ident = Ident::new(&self.modify_name, Span::call_site());
    let wrapper_arg_ident = Ident::new(WRAPPER_ARG, Span::call_site());
    let return_type = return_type_to_type(&self.annotated_fn.sig.output);
    let mut_recv = self.has_mutable_receiver().then(|| quote!(core::ptr::addr_of!(self),));
    let redefs_mut_only = self.arg_redefinitions(true);
    let modifies_closure = self.modifies_closure(
        &self.annotated_fn.sig.output,
        &self.annotated_fn.block,
        redefs_mut_only,
    );
    let result = Ident::new(INTERNAL_RESULT_IDENT, Span::call_site());
    parse_quote!(
        let #wrapper_arg_ident = (#mut_recv);
        #modifies_closure
        let #result : #return_type = #modifies_ident(#wrapper_arg_ident);
        #result
    )

pub fn check_closure(&self) -> TokenStream2 {
    let check_ident = Ident::new(&self.check_name, Span::call_site());
    let sig = &self.annotated_fn.sig;
    let output = &sig.output;
    let body_stmts = self.initial_check_stmts();
    let body = self.make_check_body(body_stmts);

    quote!(
        #[kanitool::is_contract_generated(check)]
        #[allow(dead_code, unused_variables, unused_mut)]
        let mut #check_ident = kani_force_fn_once(|| #output #body);
    )

/// Emit a modifies wrapper. It's only argument is the list of addresses that may be modified.
pub fn modifies_closure(
    &self,
    output: &ReturnType,
    body: &Block,
    redefs: TokenStream2,
) -> TokenStream2 {
    // Filter receiver
    let wrapper_ident = Ident::new(WRAPPER_ARG, Span::call_site());
    let modifies_ident = Ident::new(&self.modify_name, Span::call_site());
    let stmts = &body.stmts;
    quote!(
        #[kanitool::is_contract_generated(wrapper)]
        #[allow(dead_code, unused_variables, unused_mut)]
        let mut #modifies_ident = kani_force_fn_once_with_args(|#wrapper_ident: _| #output {
            #redefs
            #(#stmts)*
        });
    )

/// Generate argument re-definitions for arguments.
///
/// This is used so Kani doesn't think that modifying a local argument value is a side effect,
/// and avoid may-drop checks in const generic functions.
pub fn arg_redefinitions(&self, redefine_only_mut: bool) -> TokenStream2 {
    let mut result = TokenStream2::new();
    for (mutability, ident) in self.arg_bindings() {
        if mutability == MutBinding::Mut {
            result.extend(quote!(let mut #ident = #ident;));
        } else if !redefine_only_mut {
            result.extend(quote!(let #ident = #ident;));
        }
    }
    result

fn initial_replace_stmts(&self) -> Vec<syn::Stmt> {
    let return_type = return_type_to_type(&self.annotated_fn.sig.output);
    let result = Ident::new(INTERNAL_RESULT_IDENT, Span::call_site());
    // Add dummy assignments of the input variables to local variables
    // to avoid may drop checks in const generic functions.
    // https://github.com/model-checking/kani/issues/3667
    let redefs = self.arg_redefinitions(false);
    let redefs_block: Block = syn::parse_quote!({#redefs});
    [
        vec![syn::parse_quote!(
            let #result : #return_type = kani::any_modifies();
        )],
        redefs_block.stmts,
    ]
    .concat()
}

ContractConditionsData::Ensures { attr } => {
    let (remembers, ensures_clause) = build_ensures(attr);
    let ensures_bracketed = bracket_clause_expr(quote!(#ensures_clause));
    let result = Ident::new(INTERNAL_RESULT_IDENT, Span::call_site());

    let (asserts, rest_of_before) = split_for_remembers(before, ContractMode::Replace);

    quote!({
        #(#asserts)*
        #remembers
        #(#rest_of_before)*
        #(#after)*
        kani::assume(#ensures_bracketed);
        #recv_move
        #result
    })
}
ContractConditionsData::Modifies { attr } => {
    let result = Ident::new(INTERNAL_RESULT_IDENT, Span::call_site());
    let havoc_stmts: Vec<_> = attr
        .iter()
        .map(|attr| {
            let bracketed =
                bracket_clause_expr(quote!(kani::internal::untracked_deref(&#attr)));
            quote!(unsafe {
                kani::internal::write_any(kani::internal::Pointer::assignable(
                    #bracketed,
                ))
            };)
        })
        .collect();
    quote!({
        #(#before)*
        #(#havoc_stmts)*
        #(#after)*
        #recv_move
        #result
    })

pub fn replace_closure(&self) -> TokenStream {
    let replace_ident = Ident::new(&self.replace_name, Span::call_site());
    let sig = &self.annotated_fn.sig;
    let output = &sig.output;
    let before = self.initial_replace_stmts();
    let body = self.expand_replace_body(&before, &[]);

    quote!(
        #[kanitool::is_contract_generated(replace)]
        #[allow(dead_code, unused_variables, unused_mut)]
        let mut #replace_ident = kani_force_fn_once(|| #output #body);
    )

fn initial_assert_stmts(&self) -> Vec<Stmt> {
    let body_wrapper_ident = Ident::new("body_wrapper", Span::call_site());
    let output = &self.annotated_fn.sig.output;
    let return_type = return_type_to_type(output);
    let stmts = &self.annotated_fn.block.stmts;
    let result = Ident::new(INTERNAL_RESULT_IDENT, Span::call_site());

    parse_quote!(
        let mut body_wrapper = kani_force_fn_once(|| #output {
            #(#stmts)*
        });
        let #result : #return_type = #body_wrapper_ident();
        #result

ContractConditionsData::Ensures { attr } => {
    let (remembers, ensures_clause) = build_ensures(attr);
    let ensures_bracketed = bracket_clause_expr(quote!(#ensures_clause));

    let exec_postconditions = quote!(
        kani::assert(#ensures_bracketed, stringify!(#attr_copy));
    );

    let return_expr = body_stmts.pop();

    let (asserts, rest_of_body) =
        split_for_remembers(&body_stmts[..], ContractMode::Assert);

    quote!({
        #(#asserts)*
        #remembers
        #(#rest_of_body)*
        #exec_postconditions
        #return_expr
    })

let ImplItemFn { attrs, vis, defaultness, sig, block } = self.annotated_fn;
self.output.extend(quote!(
    #(#attrs)*
    #[kanitool::recursion_check = #recursion_name]
    #[kanitool::checked_with = #check_name]
    #[kanitool::replaced_with = #replace_name]
    #[kanitool::asserted_with = #assert_name]
    #[kanitool::modifies_wrapper = #modifies_name]
    #vis #defaultness #sig {
        // Dummy functions used to force the compiler to annotate Kani's
        // closures as `FnOnce`. Without this, Rust infers the generated closures as `FnMut`,
        // preventing us from writing contracts for functions returning mutable references.
        // See https://github.com/model-checking/kani/issues/3764
        #[inline(never)]
        #[kanitool::fn_marker = "kani_force_fn_once"]
        const fn kani_force_fn_once<T, F: FnOnce() -> T>(f: F) -> F {
            f
        }
        #[inline(never)]
        #[kanitool::fn_marker = "kani_force_fn_once_with_args"]
        const fn kani_force_fn_once_with_args<A, T, F: FnOnce(A) -> T>(f: F) -> F {
            f
        }
        // Dummy function used to force the compiler to capture the environment.
        // We cannot call closures inside constant functions.
        // This function gets replaced by `kani::internal::call_closure`.
        #[inline(never)]
        #[kanitool::fn_marker = "kani_register_contract"]
        const fn kani_register_contract<T, F: FnOnce() -> T>(f: F) -> T {
            unreachable!()
        }
        // Dummy function that we replace to pick the contract mode.
        // By default, return ORIGINAL.
        //
        // `#[inline]`, unlike the other markers: this is the only non-generic one, so its
        // single instantiation lives in the defining crate, and `compiler_builtins` cannot
        // call through an upstream monomorphization (rust-lang/rust#137222). `#[inline]`
        // makes rustc emit a local copy in each crate that needs it. Kani still finds the
        // call in MIR because the MIR `Inline` pass is off at Kani's default opt level.
        #[inline]
        #[kanitool::fn_marker = "kani_contract_mode"]
        const fn kani_contract_mode() -> kani::internal::Mode {
            kani::internal::ORIGINAL
        }
        let kani_contract_mode = kani_contract_mode();
        match kani_contract_mode {
            kani::internal::RECURSION_CHECK => {
                #recursion_closure;
                kani_register_contract(#recursion_ident)
            }
            kani::internal::REPLACE => {
                #replace_closure;
                kani_register_contract(#replace_ident)
            }
            kani::internal::SIMPLE_CHECK => {
                #check_closure;
                kani_register_contract(#check_ident)
            }
            kani::internal::ASSERT => {
                #assert_closure;
                kani_register_contract(#assert_ident)
            }
            _ => #block

/// If an explicit return type was provided it is returned, otherwise `()`.
pub fn return_type_to_type(return_type: &syn::ReturnType) -> Cow<'_, syn::Type> {
    match return_type {
        syn::ReturnType::Default => Cow::Owned(syn::Type::Tuple(syn::TypeTuple {
            paren_token: syn::token::Paren::default(),
            elems: Default::default(),
        })),
        syn::ReturnType::Type(_, typ) => Cow::Borrowed(typ.as_ref()),
    }

pub fn is_token_stream_2_comma(t: &proc_macro2::TokenTree) -> bool {
    matches!(t, proc_macro2::TokenTree::Punct(p) if p.as_char() == ',')
}

pub fn chunks_by<'a, T, C: Default + Extend<T>>(
    i: impl IntoIterator<Item = T> + 'a,
    mut pred: impl FnMut(&T) -> bool + 'a,
) -> impl Iterator<Item = C> + 'a {
    let mut iter = i.into_iter();
    std::iter::from_fn(move || {
        let mut new = C::default();
        let mut empty = true;
        for tok in iter.by_ref() {
            empty = false;
            if pred(&tok) {
                break;
            } else {
                new.extend([tok])
            }
        }
        (!empty).then_some(new)
    })

pub fn bracket_clause_expr(expr: proc_macro2::TokenStream) -> proc_macro2::TokenStream {
    quote::quote!({
        let __kani_clause_guard = kani::internal::enter_contract_clause_guard();
        let __kani_clause_value = #expr;
        __kani_clause_value
    })
}

/// Wrap a contract clause *statement* (e.g. `kani::assume(#cond);` or
/// `kani::assert(#cond, ..);`) in a scope that increments the clause-depth
/// counter for its duration, via the same RAII guard as [`bracket_clause_expr`].
///
/// Unlike [`bracket_clause_expr`], the clause expression is left in place as a
/// direct argument to `assume`/`assert` rather than moved behind a wrapper
/// block. This preserves its span, so that a non-`bool` clause reports the
/// type error on the offending sub-expression rather than on the generated
/// wrapper (see tests/ui/function-contracts/non_bool_contracts.rs and
/// https://github.com/model-checking/kani/issues/3009). The guard is still
/// dropped on all exits from the scope, including unwinding.
pub fn bracket_clause_stmt(stmt: proc_macro2::TokenStream) -> proc_macro2::TokenStream {
    quote::quote!({
        let __kani_clause_guard = kani::internal::enter_contract_clause_guard();
        #stmt
    })
}

/// This should only be used within contracts. The intent is to
/// perform type inference on a closure's argument
#[doc(hidden)]
pub fn apply_closure<T, U: Fn(&T) -> bool>(f: U, x: &T) -> bool {
    f(x)
}

#[crate::kani::unstable_feature(
    feature = "mem-predicates",
    issue = 2690,
    reason = "experimental memory predicate API"
)]
pub fn can_write<T: MetaSized>(ptr: *mut T) -> bool {
    is_ptr_aligned(ptr) && is_inbounds(ptr)
}

/// Check if the pointer is valid for unaligned write access according to [crate::mem] conditions
/// 1, 2 and 3.
///
/// Note this function succeeds for unaligned pointers. See [self::can_write] if you also

    feature = "mem-predicates",
    issue = 2690,
    reason = "experimental memory predicate API"
)]
#[allow(clippy::not_unsafe_ptr_arg_deref)]
pub fn can_dereference<T: MetaSized>(ptr: *const T) -> bool {
    // Need to assert `is_initialized` because non-determinism is used under the hood, so it
    // does not make sense to use it inside assumption context.
    is_ptr_aligned(ptr)
        && is_inbounds(ptr)
        && assert_is_initialized(ptr)
        && unsafe { has_valid_value(ptr) }
}

    feature = "mem-predicates",
    issue = 2690,
    reason = "experimental memory predicate API"
)]
#[allow(clippy::not_unsafe_ptr_arg_deref)]
pub fn same_allocation<T: PointeeSized>(ptr1: *const T, ptr2: *const T) -> bool {
    same_allocation_internal(ptr1, ptr2)
}

#[allow(clippy::not_unsafe_ptr_arg_deref)]
pub(super) fn same_allocation_internal<T: PointeeSized>(
    ptr1: *const T,
    ptr2: *const T,
) -> bool {
    let addr1 = ptr1 as *const ();
    let addr2 = ptr2 as *const ();
    cbmc::same_allocation(addr1, addr2)
}

/// Check that all crate items are supported and there's no misconfiguration.
/// This method will exhaustively print any error / warning and it will abort at the end if any
/// error was found.
pub fn check_crate_items(tcx: TyCtxt, ignore_asm: bool) {
    let krate = tcx.crate_name(LOCAL_CRATE);
    let mut all_stub_verified_targets = FxHashMap::default();
    let mut all_contract_targets = HashSet::new();

    for item in tcx.hir_free_items() {
        let def_id = item.owner_id.def_id.to_def_id();
        let (stub_verified_targets, contract_targets) =
            KaniAttributes::for_item(tcx, def_id).check_attributes();
        all_stub_verified_targets.extend(stub_verified_targets);
        all_contract_targets.extend(contract_targets);

// Validate that all stub_verified targets have corresponding proof_for_contract harnesses
for (stub_verified_target, span) in all_stub_verified_targets {
    if !all_contract_targets.contains(&stub_verified_target) {
        tcx.dcx().struct_span_err(
            span,
            format!(
                "stub verified target `{}` does not have a corresponding `#[proof_for_contract]` harness",
                strip_local_crate_prefix(stub_verified_target.name())
            ),
        ).with_help("verified stubs are meant to be sound abstractions for a function's behavior, so Kani enforces that proofs exist for the stub's contract")
        .emit();
    }
}

tcx.dcx().abort_if_errors();

fn handle_proof_for_contract(&self, attr: &Attribute) {
    let target_def = match self.interpret_for_contract_attribute() {
        None => return, // This error was already emitted
        Some(def) => def,
    };
    let target_attributes = KaniAttributes::for_def_id(self.tcx, target_def.def_id());
    if target_attributes.contract_attributes().is_none() {
        self.tcx
            .dcx()
            .struct_span_err(
                attr.span(),
                format!(
                    "Failed to check contract: `{}` has no contract.",
                    target_attributes.item_name(),
                ),
            )
            .with_span_note(
                rustc_internal::internal(self.tcx, target_def.span()),
                "Try adding a contract to this function.",
            )
            .emit();
    }

fn check_stub_verified(&self, attr: &Attribute) {
    let dcx = self.tcx.dcx();
    let mut seen = HashSet::new();
    for stub_target in self.interpret_stub_verified_attribute() {
        if seen.contains(&stub_target) {
            dcx.struct_span_warn(
                rustc_internal::internal(self.tcx, stub_target.span()),
                format!(
                    "Multiple occurrences of `stub_verified({})`.",
                    stub_target.trimmed_name()
                ),
            )
            .with_help("Use a single annotation instead.")
            .emit();
        } else {
            seen.insert(stub_target);
        }
        if KaniAttributes::for_def_id(self.tcx, stub_target.def_id())
            .contract_attributes()
            .is_none()
        {
            dcx.struct_span_err(
                attr.span(),
                format!(
                    "Target function in stub_verified, `{}`, has no contract.",
                    stub_target.trimmed_name()
                ),
            )
                .with_span_note(
                    rustc_internal::internal(self.tcx, stub_target.span()),
                    format!(
                        "Try adding a contract to this function or use the unsound `{}` attribute instead.",
                        KaniAttributeKind::Stub.as_ref(),
                    ),
                )
                .emit();
